import{_ as e,o as t,c as l,a2 as i}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"3.2 观察桌面与人工接管","description":"让用户看见操作过程，并能暂停、接管和交还。","frontmatter":{"title":"3.2 观察桌面与人工接管","description":"让用户看见操作过程，并能暂停、接管和交还。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-3/3-2.md","filePath":"delivery/stage-3/3-2.md","lastUpdated":1794017073000}'),r={name:"delivery/stage-3/3-2.md"};function o(n,a,s,d,_,h){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="_3-2-观察桌面与人工接管" tabindex="-1">3.2 观察桌面与人工接管 <a class="header-anchor" href="#_3-2-观察桌面与人工接管" aria-label="Permalink to &quot;3.2 观察桌面与人工接管&quot;">​</a></h1><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><ul><li><strong>已实现：</strong> 截图绑定当前会话；暂停、继续、接管、交还、终止；接管会取消待执行输入并推进控制代次；用户输入空闲检查和截图 2 分钟过期。</li><li><strong>仍未完成：</strong> 敏感区域遮罩、长期录像和完整桌面快照。</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>让用户能看见 Hearth 正在操作的窗口和步骤，并在需要时暂停自动操作、自己接管、完成后再交还。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>显示当前窗口、操作步骤和下一步计划，避免用户不知道系统在做什么。</li><li>提供暂停、继续、接管和终止四个明确动作。</li><li>用户接管时立即停止自动输入，交还时先确认当前状态再继续。</li><li>对密码、聊天内容等敏感区域做遮挡，不把完整屏幕长期保存。</li><li>记录每次接管、暂停和终止的原因，方便事后核对。</li><li>如果无法观察窗口或无法接管，系统必须停下，不允许继续自动操作。</li></ol>',7)])])}const p=e(r,[["render",o]]);export{u as __pageData,p as default};
